SELECT COUNT(*) AS river_count
FROM river
WHERE river.traverse = (SELECT state_name FROM state ORDER BY state_name DESC LIMIT 1);

SELECT fname, lname
FROM employee
WHERE hire_date < '1990-01-01';

SELECT SUM(amount) AS total_amount
FROM payment
WHERE payment_date BETWEEN '2005-08-01' AND '2005-08-31';

SELECT COUNT(DISTINCT student.StuID) AS student_count
FROM Student student
JOIN Plays_Games pg ON student.StuID = pg.StuID;

SELECT student_id
FROM Student_Course_Registrations
WHERE course_id = 301;

SELECT grant_id, MAX(documents) AS max_docs
FROM (
    SELECT grant_id, COUNT(*) AS documents
    FROM Documents
    GROUP BY grant_id
);

SELECT COUNT(*) AS citation_count
FROM publication
WHERE citation_num < 2010;

SELECT COUNT(DISTINCT s.student_id) AS num_students
FROM Students s
JOIN Student_Course_Enrolment ce ON s.student_id = ce.student_id;

SELECT employee.fname, employee.lname
FROM employee
WHERE employee.hire_date < '1990-01-01';

SELECT AVG(m.Number_cities) FROM film_market_estimation AS fmi
JOIN market AS m ON fmi.Market_ID = m.Market_ID
WHERE fmi.Estimation_ID = (SELECT Estimation_ID FROM film_market_estimation ORDER BY Low_Estimate DESC LIMIT 1);

SELECT COUNT(DISTINCT a.last_name) AS last_names
FROM actor a
WHERE a.actor_id IN (SELECT actor_id FROM film_actor);

SELECT document_type_code
FROM Document_Types
WHERE document_type_code LIKE 'APP%';

SELECT COUNT(*) AS count
FROM Genes
WHERE Genes.Phenotype = 'Nucleic acid metabolism defects' AND Genes.Chromosome = 1;

SELECT a.address, a.address2, a.district
FROM address a
WHERE a.address_id = 2;

SELECT current.birthday_bio
FROM current
WHERE current.official_full_name = 'Amy Klobuchar';

SELECT DISTINCT d.Home_city
FROM driver d
WHERE d.Home_city NOT IN (SELECT d2.Home_city FROM driver d2 WHERE d2.Age > 40);

SELECT COUNT(DISTINCT r.traverse) AS state_count
FROM river AS r
WHERE r.traverse = 'missouri';

SELECT COUNT(DISTINCT item.i_id) AS item_count
FROM review
JOIN item ON review.i_id = item.i_id;
